/// <summary>
///     Data provider class for <c>AVASalesQuotationRequestStatsReport</c> SSRS report
/// </summary>
/// <remarks>
///     This is the Data provider class for the <c>AVASalesQuotationRequestStatsReport</c> SSRS Report.
/// </remarks>
[
    ////SRSReportQueryAttribute(queryStr(AVASalesQuotationRequestStatsReportQry)),
    //SRSReportParameterAttribute(classStr(AVASalesQuotationRequestStatsReportContract))
    SRSReportQueryAttribute(queryStr(AVASalesQuotationRequestStatsReportQry)),
    SRSReportParameterAttribute(classStr(AVASalesQuotationRequestStatsReportContract))
]
class AVASalesQuotationRequestStatsReportDP extends SrsReportDataProviderPreProcess //SRSReportDataProviderBase
{
    AVASalesQuotRequestStatsReportHeaderTmp         clsHeaderTmp;
    AVASalesQuotRequestStatsReportHeaderTmp         clsHeaderTmpBase;
    AVASalesQuotRequestStatsReportDetailTmp         clsDetailTmp;
    AVASalesQuotRequestStatsReportDetailTmp         clsDetailTmpBase;

    CompanyInfo                                     clsCompanyInfo;
    CompanyImage                                    clsCompanyLogo;
    Bitmap                                          clsCompanyLogoBitmap;
    container                                       clsAllBPCompanies;

    SysDocuBrandDetails                             clsSysDocuBrandDetails;

    SalesQuotationTable                             clsSalesQuotationTable;
    smmBusRelTable                                  clsSmmBusRelTable;
    CustTable                                       clsCustTable;
    CommissionSalesGroup                            clsCommissionSalesGroup;
    KCS_KBVRequestTable                             clsKCS_KBVRequestTable;
    KCS_KBVBuildingProjectTable                     clsKCS_KBVBuildingProjectTable;

    SalesQuotationLine                              clsSalesLine;
    KCS_SOCSalesTableInfoFields                     clsKCS_SOCSalesTableInfoFields;

    AVASalesQuotationRequestStatsReportContract     clsReportContract;
    RefRecId                                        clsSalesQuotationTableRecId;

    QuotationId                                     clsQuotationId;
    smmBusRelAccount                                clsSmmBusRelAccount;
    CustAccount                                     clsCustAccount;
    CommissSalesGroup                               clsKCS_CommissSalesGroup;
    Name                                            clsKCS_CommissSalesGroupLike;
    CreatedDateTime                                 clsQuotationCreatedDateTime;

    DirPartyRecId                                   clsRequestDirPartyId;
    KCS_KBVReceiptDate                              clsKCS_KBVReceiptDate;
    KCS_KBVReceiptDate                              clsKCS_KBVReceiptDateTo;

    KCS_KBVRequestID                                clsKCS_KBVRequestID;
    KCS_KBVBuildingProjectID                        clsKCS_KBVBuildingProjectID;

    SalesTotals                                     clsSalesTotals;
    MarkupValue                                     clsMarkupValueSum;

    UnitOfMeasure                                   clsUnitOfMeasure;
    UnitOfMeasureConverter_Product                  clsUnitOfMeasureConverter_Product;

    int                                             clsAdditionalInfoLevel;

    str                                             clsQuotationIdRange;
    str                                             clsSmmBusRelAccountRange;
    str                                             clsCustAccountRange;
    str                                             clsKCS_CommissSalesGroupRange;
    str                                             clsKCS_CommissSalesGroupNameRange;
    str                                             clsQuotationCreatedDateTimeRange;
    str                                             clsRequestDirPartyIdRange;
    str                                             clsKCS_KBVReceiptDateRange;
    str                                             clsKCS_KBVRequestIDRange;
    str                                             clsKCS_KBVBuildingProjectIDRange;

}

